#!/usr/bin/env python3
"""ARC task task-d2e27133 - Transform minority to 0, majority to minority_value"""

def transform(grid):
    """Apply the ARC transformation: minority -> 0, majority -> minority_value"""
    # Count occurrences of each value
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1

    # Find minority and majority
    minority = min(counts, key=lambda x: counts[x])
    majority = max(counts, key=lambda x: counts[x])

    # Apply transformation
    result = [[minority if v == majority else 0 for v in row] for row in grid]
    return result

if __name__ == "__main__":
    pass
